async function complete(job: ClaimedJob<ReceiptJob>): Promise<void> {
  // A receipt claimed before the customer was erased keeps its amounts but names nobody.
  const suppressed = await isCustomerSuppressed(job.merchant_id, job.payload.customerId);
  const stored = await storeReceipt(suppressed
    ? { ...job.payload, customerSnapshot: redactPii(job.payload.customerSnapshot) as Record<string, unknown> }
    : job.payload);

