helper = """
  /** Refuses writes once deletion is requested, so cleanup cannot be outrun by new data. */
  private async assertNotErased(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    if (await isCustomerSuppressedInTransaction(client, merchantId, customerId)) {
      throw Object.assign(new Error('customer data deletion requested'), { statusCode: 409 });
    }
  }

  private eventPayload(row: CustomerRow)"""
s = s.replace("\n  private eventPayload(row: CustomerRow)", helper, 1)
open(p,'w').write(s)
