import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '/workspace/source/packages/config/src/index.js';
import { pool } from '/workspace/source/packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '/workspace/source/packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '/workspace/source/packages/storage/src/minio.js';
import { producer, DOMAIN_TOPIC } from '/workspace/source/packages/messaging/src/kafka.js';

const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';
const otherKey = 'pf_local_dev_bluebird_924bd90d2201';

async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}, key = apiKey) {
  const init: RequestInit = { method, headers: { authorization: `Bearer ${key}`, ...headers } };
  if (body !== undefined) {
    (init.headers as Record<string, string>)['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  const text = await response.text();
  return { status: response.status, body: text ? JSON.parse(text) : undefined };
}

// Build a fresh subject with a full trail of activity.
const suffix = randomUUID().slice(0, 8);
const person = { externalReference: `erasure-${suffix}`, email: `erasure.${suffix}@example.test`, name: 'Subject Under Erasure', phone: '+1-415-555-0199' };
const customer = (await api('/v1/customers', 'POST', { ...person, metadata: { segment: 'retail' } })).body;
const kept = (await api('/v1/customers', 'POST', { externalReference: `kept-${suffix}`, email: `kept.${suffix}@example.test`, name: 'Kept Customer' })).body;
await api(`/v1/customers/${customer.id}/addresses`, 'POST', { kind: 'billing', line1: '1 Privacy Way', city: 'Berlin', postalCode: '10115', country: 'DE' });
await api(`/v1/customers/${customer.id}/contacts`, 'POST', { kind: 'email', value: person.email, isPrimary: true });
const method = (await api(`/v1/customers/${customer.id}/payment-methods`, 'POST', { providerToken: `tok_erasure_${randomUUID()}`, type: 'card', brand: 'visa', last4: '4242', billingName: person.name })).body;
await api(`/v1/customers/${customer.id}/support-tickets`, 'POST', { subject: 'Please call me', body: `Reach me at ${person.email} or ${person.phone}` });
await api('/v1/customer-imports', 'POST', { source: 'legacy-crm', record: { customerId: customer.id, ...person } });
const invoice = (await api('/v1/invoices', 'POST', { customerId: customer.id, currency: 'USD', tax: 100, lines: [{ description: 'Subscription', quantity: 1, unitAmount: 4000 }] })).body;
const payment = (await api('/v1/payments', 'POST', { customerId: customer.id, paymentMethodId: method.id, amount: 3300, currency: 'USD', description: 'Order' }, { 'idempotency-key': `erasure-pay-${suffix}` })).body;

// A shared ticket that must survive: another customer stays in the conversation.
const sharedTicket = await pool.query<{ id: string }>(
  `INSERT INTO customers.support_tickets(merchant_id,subject) VALUES($1,'Shared thread') RETURNING id`,
  ['10000000-0000-4000-8000-000000000001'],
);
await pool.query(`INSERT INTO customers.support_participants(ticket_id,customer_id) VALUES($1,$2),($1,$3)`,
  [sharedTicket.rows[0]!.id, customer.id, kept.id]);
await pool.query(
  `INSERT INTO customers.support_messages(merchant_id,ticket_id,author_type,author_id,body)
   VALUES($1,$2,'customer',$3,$4),($1,$2,'customer',$5,'Me too')`,
  ['10000000-0000-4000-8000-000000000001', sharedTicket.rows[0]!.id, customer.id, `my email is ${person.email}`, kept.id],
);

await new Promise((resolve) => setTimeout(resolve, 4_000));
await api(`/v1/payments/${payment.id}/refunds`, 'POST', { amount: 300, reason: 'partial refund' });
await new Promise((resolve) => setTimeout(resolve, 3_000));

const before = await pool.query<{ n: string }>(
  `SELECT count(*)::text n FROM payments.ledger_postings p JOIN payments.ledger_entries e ON e.id=p.entry_id
   WHERE e.merchant_id=$1`, ['10000000-0000-4000-8000-000000000001']);

// --- API contract ---
assert.equal((await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': 'short' })).status, 400, 'idempotency key required');
assert.equal((await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `missing-${suffix}` })).status, 404, 'unknown customer');
assert.equal((await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `x-tenant-${suffix}` }, otherKey)).status, 404, 'other merchant cannot erase');

const key = `erase-${suffix}`;
const accepted = await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(accepted.status, 202, JSON.stringify(accepted));
assert.deepEqual(Object.keys(accepted.body).sort(), ['attempts', 'completedAt', 'createdAt', 'customerId', 'id', 'lastError', 'status', 'updatedAt']);
assert.equal(accepted.body.customerId, customer.id);
assert.ok(['pending', 'processing', 'completed'].includes(accepted.body.status), accepted.body.status);

const replay = await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(replay.status, 202);
assert.equal(replay.body.id, accepted.body.id, 'same key returns the same request');
const conflict = await api(`/v1/customers/${kept.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': key });
assert.equal(conflict.status, 409, 'key reuse for another customer conflicts');
const freshKey = await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `${key}-2` });
assert.equal(freshKey.body.id, accepted.body.id, 'a new key returns the existing request');

assert.equal((await api(`/v1/erasure-requests/${accepted.body.id}`, 'GET', undefined, {}, otherKey)).status, 404, 'status is tenant scoped');
assert.equal((await api(`/v1/erasure-requests/${randomUUID()}`)).status, 404, 'unknown request');

let status = accepted.body;
for (let attempt = 0; attempt < 60 && status.status !== 'completed'; attempt += 1) {
  await new Promise((resolve) => setTimeout(resolve, 500));
  status = (await api(`/v1/erasure-requests/${accepted.body.id}`)).body;
}
assert.equal(status.status, 'completed', `request did not complete: ${JSON.stringify(status)}`);
assert.ok(status.completedAt, 'completedAt must be set');
assert.equal(status.lastError, null);

// --- personal data is gone, financial facts remain ---
const remaining = await pool.query<Record<string, string>>(`
  SELECT
    (SELECT count(*) FROM customers.customers WHERE id=$2)::text customers,
    (SELECT count(*) FROM customers.addresses WHERE customer_id=$2)::text addresses,
    (SELECT count(*) FROM customers.contacts WHERE customer_id=$2)::text contacts,
    (SELECT count(*) FROM customers.payment_method_refs WHERE customer_id=$2)::text methods,
    (SELECT count(*) FROM customers.provider_customer_mappings WHERE customer_id=$2)::text mappings,
    (SELECT count(*) FROM customers.support_messages WHERE author_id=$2)::text messages,
    (SELECT count(*) FROM customers.support_participants WHERE customer_id=$2)::text participants,
    (SELECT count(*) FROM provider_sandbox.customers WHERE payflow_customer_id=$2)::text provider_customers,
    (SELECT count(*) FROM operations.notifications WHERE customer_id=$2)::text notifications,
    (SELECT count(*) FROM operations.email_deliveries WHERE customer_id=$2)::text emails,
    (SELECT count(*) FROM operations.notification_preferences WHERE customer_id=$2)::text preferences,
    (SELECT count(*) FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)::text payments,
    (SELECT count(*) FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2)::text invoices,
    (SELECT count(*) FROM payments.captures c JOIN payments.payment_intents p ON p.id=c.payment_intent_id
      WHERE p.customer_id=$2)::text captures,
    (SELECT count(*) FROM payments.refunds r JOIN payments.payment_intents p ON p.id=r.payment_intent_id
      WHERE p.customer_id=$2)::text refunds,
    (SELECT count(*) FROM payments.ledger_postings p JOIN payments.ledger_entries e ON e.id=p.entry_id
      WHERE e.merchant_id=$1)::text postings,
    (SELECT count(*) FROM customers.support_tickets WHERE id=$3)::text shared_ticket,
    (SELECT count(*) FROM customers.support_messages WHERE ticket_id=$3)::text shared_messages,
    (SELECT count(*) FROM customers.customers WHERE id=$4)::text kept_customer,
    (SELECT total FROM payments.payment_intents WHERE id=$5) IS NOT NULL::text AS dummy,
    (SELECT amount::text FROM payments.payment_intents WHERE id=$5) payment_amount,
    (SELECT status FROM payments.payment_intents WHERE id=$5) payment_status,
    (SELECT total::text FROM payments.invoices WHERE id=$6) invoice_total
`.replace("    (SELECT total FROM payments.payment_intents WHERE id=$5) IS NOT NULL::text AS dummy,\n", ""),
  ['10000000-0000-4000-8000-000000000001', customer.id, sharedTicket.rows[0]!.id, kept.id, payment.id, invoice.id]);
const state = remaining.rows[0]!;
assert.equal(state.customers, '0', 'customer identity row remains');
for (const field of ['addresses', 'contacts', 'methods', 'mappings', 'messages', 'participants',
  'provider_customers', 'notifications', 'emails', 'preferences']) {
  assert.equal(state[field], '0', `${field} still holds personal data`);
}
assert.equal(state.payments, '1', 'payment record must be retained');
assert.equal(state.payment_amount, '3300', 'payment amount must be unchanged');
assert.equal(state.payment_status, 'partially_refunded', 'payment status must be unchanged');
assert.equal(state.invoices, '1', 'invoice must be retained');
assert.equal(state.invoice_total, '4100', 'invoice total must be unchanged');
assert.equal(state.captures, '1', 'capture must be retained');
assert.equal(state.refunds, '1', 'refund must be retained');
assert.equal(state.postings, before.rows[0]!.n, 'ledger postings must be untouched');
assert.equal(state.shared_ticket, '1', 'shared ticket must survive for the remaining participant');
assert.equal(state.shared_messages, '1', 'the other participant keeps their message');
assert.equal(state.kept_customer, '1', 'another customer must not be affected');

const leaked = await pool.query<{ location: string }>(`
  SELECT 'payment_snapshot' location FROM payments.payment_intents
    WHERE customer_snapshot::text ILIKE '%' || $1 || '%' OR customer_snapshot::text ILIKE '%' || $2 || '%'
  UNION ALL SELECT 'payment_attempt' FROM payments.payment_attempts
    WHERE request_payload::text ILIKE '%'||$1||'%' OR COALESCE(response_payload::text,'') ILIKE '%'||$1||'%'
  UNION ALL SELECT 'refund' FROM payments.refunds WHERE COALESCE(customer_email,'') ILIKE '%'||$1||'%'
  UNION ALL SELECT 'invoice' FROM payments.invoices WHERE billing_snapshot::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'outbox' FROM operations.outbox_events WHERE payload::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'analytics' FROM operations.analytics_events
    WHERE COALESCE(email,'') ILIKE '%'||$1||'%' OR properties::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'jobs' FROM operations.jobs WHERE payload::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'dead_letters' FROM operations.dead_letters WHERE payload::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'audit' FROM platform.audit_logs WHERE metadata::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'manifests' FROM operations.document_manifests WHERE metadata::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 'idempotency' FROM operations.idempotency_keys
    WHERE COALESCE(response_body::text,'') ILIKE '%'||$1||'%'
  UNION ALL SELECT 'support' FROM customers.support_messages WHERE body ILIKE '%'||$1||'%'
  UNION ALL SELECT 'imports' FROM customers.customer_imports WHERE object_key ILIKE '%'||$1||'%'
  UNION ALL SELECT 'sandbox' FROM provider_sandbox.customers WHERE email ILIKE '%'||$1||'%'
`, [person.email, person.phone]);
assert.equal(leaked.rowCount, 0, `personal data left in: ${JSON.stringify(leaked.rows)}`);

const redis = new Redis(config().REDIS_URL);
const cacheKey = `merchant:10000000-0000-4000-8000-000000000001:customer:${customer.id}`;
assert.equal(await redis.exists(cacheKey), 0, 'redis projection remains');
assert.equal(await redis.exists(`${cacheKey}:activity`), 0, 'redis activity remains');
assert.equal(await redis.exists(`merchant:10000000-0000-4000-8000-000000000001:customer:${kept.id}`), 1,
  'another customer lost its projection');

await searchClient.indices.refresh({ index: CUSTOMER_INDEX });
const search = await searchClient.search({ index: CUSTOMER_INDEX, body: { query: { term: { customerId: customer.id } } } });
assert.equal((search.body.hits.total as { value: number }).value, 0, 'search index still exposes the customer');
const keptSearch = await searchClient.search({ index: CUSTOMER_INDEX, body: { query: { term: { customerId: kept.id } } } });
assert.equal((keptSearch.body.hits.total as { value: number }).value, 1, 'another customer lost its search document');

const objects = await pool.query<{ object_key: string; document_type: string }>(
  `SELECT object_key,document_type FROM operations.document_manifests WHERE merchant_id=$1`,
  ['10000000-0000-4000-8000-000000000001']);
for (const object of objects.rows) {
  const stream = await objectStore.getObject(DOCUMENT_BUCKET, object.object_key);
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(Buffer.from(chunk as Buffer));
  const content = chunks.join('');
  assert.ok(!content.includes(person.email), `${object.object_key} still contains the email`);
  assert.ok(!content.includes(person.name), `${object.object_key} still contains the name`);
  assert.ok(!content.includes(person.phone), `${object.object_key} still contains the phone`);
}
const retainedInvoice = objects.rows.find((row) => row.object_key.includes(`invoices/${invoice.id}`));
assert.ok(retainedInvoice, 'invoice document must be retained');
const invoiceStream = await objectStore.getObject(DOCUMENT_BUCKET, retainedInvoice.object_key);
const invoiceChunks: Buffer[] = [];
for await (const chunk of invoiceStream) invoiceChunks.push(Buffer.from(chunk as Buffer));
const invoiceDocument = JSON.parse(invoiceChunks.join('')) as { total: number; customer: unknown };
assert.equal(invoiceDocument.total, 4100, 'retained invoice lost its financial meaning');
assert.equal(invoiceDocument.customer, null, 'retained invoice still identifies the customer');

const mail = await (await fetch(`${config().MAILPIT_API_URL}/api/v1/search?query=${encodeURIComponent(`to:${person.email}`)}`)).json() as { messages?: unknown[] };
assert.equal((mail.messages ?? []).length, 0, 'captured provider mail still addresses the customer');

// --- delayed work must not restore anything ---
const kafka = producer();
await kafka.connect();
await kafka.send({
  topic: DOMAIN_TOPIC,
  messages: [{
    key: customer.id,
    value: JSON.stringify({
      eventId: randomUUID(), eventType: 'customer.created.v1', eventVersion: 1,
      occurredAt: new Date().toISOString(), aggregateType: 'customer', aggregateId: customer.id,
      merchantId: '10000000-0000-4000-8000-000000000001', correlationId: randomUUID(),
      payload: { customerId: customer.id, ...person },
    }),
  }, {
    key: customer.id,
    value: JSON.stringify({
      eventId: randomUUID(), eventType: 'payment.succeeded.v1', eventVersion: 1,
      occurredAt: new Date().toISOString(), aggregateType: 'payment_intent', aggregateId: payment.id,
      merchantId: '10000000-0000-4000-8000-000000000001', correlationId: randomUUID(),
      payload: { paymentId: payment.id, customerId: customer.id, amount: 3300, currency: 'USD', customerEmail: person.email },
    }),
  }],
});
await kafka.disconnect();
await new Promise((resolve) => setTimeout(resolve, 6_000));

await searchClient.indices.refresh({ index: CUSTOMER_INDEX });
const afterReplay = await searchClient.search({ index: CUSTOMER_INDEX, body: { query: { term: { customerId: customer.id } } } });
assert.equal((afterReplay.body.hits.total as { value: number }).value, 0, 'a replayed event restored the search document');
assert.equal(await redis.exists(cacheKey), 0, 'a replayed event restored the cache entry');
const replayLeak = await pool.query(`
  SELECT 1 FROM operations.analytics_events
    WHERE COALESCE(email,'') ILIKE '%'||$1||'%' OR properties::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 1 FROM operations.email_deliveries WHERE destination ILIKE '%'||$1||'%'
  UNION ALL SELECT 1 FROM operations.notifications WHERE destination ILIKE '%'||$1||'%'
  UNION ALL SELECT 1 FROM operations.notification_preferences WHERE destination ILIKE '%'||$1||'%'
`, [person.email]);
assert.equal(replayLeak.rowCount, 0, 'a replayed event restored personal data');
const replayMail = await (await fetch(`${config().MAILPIT_API_URL}/api/v1/search?query=${encodeURIComponent(`to:${person.email}`)}`)).json() as { messages?: unknown[] };
assert.equal((replayMail.messages ?? []).length, 0, 'a replayed event mailed the erased customer');

// New activity for the erased customer must be refused.
