  SELECT 1 FROM operations.analytics_events
    WHERE COALESCE(email,'') ILIKE '%'||$1||'%' OR properties::text ILIKE '%'||$1||'%'
  UNION ALL SELECT 1 FROM operations.email_deliveries WHERE destination ILIKE '%'||$1||'%'
  UNION ALL SELECT 1 FROM operations.notifications WHERE destination ILIKE '%'||$1||'%'
  UNION ALL SELECT 1 FROM operations.notification_preferences WHERE destination ILIKE '%'||$1||'%'
`, [person.email]);
assert.equal(replayLeak.rowCount, 0, 'a replayed event restored personal data');
