assert.equal((replayMail.messages ?? []).length, 0, 'a replayed event mailed the erased customer');

// New activity for the erased customer must be refused.
const newPayment = await api('/v1/payments', 'POST', { customerId: customer.id, paymentMethodId: method.id, amount: 100, currency: 'USD' }, { 'idempotency-key': `after-erasure-${suffix}` });
assert.ok(newPayment.status >= 400, `payments for an erased customer must fail: ${JSON.stringify(newPayment)}`);
