action.file_text:
import { pool } from '../packages/database/src/pool.js';

const needles = process.argv.slice(2);
const columns = await pool.query<{ table_schema: string; table_name: string; column_name: string }>(
  `SELECT c.table_schema,c.table_name,c.column_name
   FROM information_schema.columns c
   JOIN information_schema.tables t
     ON t.table_schema=c.table_schema AND t.table_name=c.table_name AND t.table_type='BASE TABLE'
   WHERE c.table_schema IN ('platform','customers','payments','operations','provider_sandbox','privacy','public')
     AND c.data_type IN ('text','character varying','jsonb','json','character')`,
);
const findings: string[] = [];
for (const column of columns.rows) {
  for (const needle of needles) {
    const result = await pool.query<{ n: string }>(
      `SELECT count(*)::text n FROM "${column.table_schema}"."${column.table_name}"
       WHERE "${column.column_name}"::text ILIKE '%' || $1 || '%'`,
      [needle],
    );
    if (Number(result.rows[0]!.n) > 0) {
      findings.push(`${column.table_schema}.${column.table_name}.${column.column_name} (${result.rows[0]!.n}) <- ${needle}`);
    }
  }
}
console.log(findings.length ? findings.join('\n') : 'no personal data found in any column');
await pool.end();

