import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { pool } from '../packages/database/src/pool.js';

const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';
const merchantId = '10000000-0000-4000-8000-000000000001';

async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}) {
  const init: RequestInit = { method, headers: { authorization: `Bearer ${apiKey}`, ...headers } };
  if (body !== undefined) {
    (init.headers as Record<string, string>)['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  const text = await response.text();
  return { status: response.status, body: text ? JSON.parse(text) : undefined };
}

// A 404 must not leave a trace behind.
const unknownId = randomUUID();
const unknownKey = `ghost-${randomUUID()}`;
assert.equal((await api(`/v1/customers/${unknownId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': unknownKey })).status, 404);
const traces = await pool.query(
  `SELECT 1 FROM operations.idempotency_keys WHERE merchant_id=$1 AND key=$2
   UNION ALL SELECT 1 FROM privacy.erasure_requests WHERE customer_id=$3
   UNION ALL SELECT 1 FROM privacy.erased_customers WHERE customer_id=$3`,
  [merchantId, unknownKey, unknownId]);
assert.equal(traces.rowCount, 0, 'a rejected request changed data');

const suffix = randomUUID().slice(0, 8);
const person = { externalReference: `resume-${suffix}`, email: `resume.${suffix}@example.test`, name: 'Resume Subject', phone: '+1-415-555-0177' };
const customer = (await api('/v1/customers', 'POST', person)).body;
await api(`/v1/customers/${customer.id}/contacts`, 'POST', { kind: 'email', value: person.email, isPrimary: true });
await new Promise((resolve) => setTimeout(resolve, 2_000));

const accepted = await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `resume-${suffix}` });
assert.equal(accepted.status, 202);

// Simulate a crash after the external systems were cleaned: the request is left
// leased by a worker that never comes back.
await pool.query(
  `UPDATE privacy.erasure_requests
   SET status='processing',locked_by='crashed-worker',locked_at=now(),lease_expires_at=now()-interval '1 minute'
   WHERE id=$1`, [accepted.body.id]);
await pool.query(
  `INSERT INTO privacy.erasure_request_steps(request_id,step) VALUES($1,'search'),($1,'cache')
   ON CONFLICT DO NOTHING`, [accepted.body.id]);

let status = (await api(`/v1/erasure-requests/${accepted.body.id}`)).body;
const seen = new Set<string>([status.status]);
for (let attempt = 0; attempt < 160 && status.status !== 'completed'; attempt += 1) {
  await new Promise((resolve) => setTimeout(resolve, 500));
  status = (await api(`/v1/erasure-requests/${accepted.body.id}`)).body;
  seen.add(status.status);
}
assert.equal(status.status, 'completed', `did not resume: ${JSON.stringify(status)}`);
assert.ok(status.attempts >= 1, 'attempts must be reported');
assert.equal(status.id, accepted.body.id, 'the request id must be stable across retries');

const leftovers = await pool.query(
  `SELECT 1 FROM customers.customers WHERE id=$1
   UNION ALL SELECT 1 FROM customers.contacts WHERE customer_id=$1
   UNION ALL SELECT 1 FROM operations.analytics_events
     WHERE COALESCE(email,'') = $2 OR properties::text ILIKE '%'||$2||'%'`,
  [customer.id, person.email]);
assert.equal(leftovers.rowCount, 0, 'resumed run left personal data behind');
const steps = await pool.query<{ step: string }>(
  `SELECT step FROM privacy.erasure_request_steps WHERE request_id=$1 ORDER BY step`, [accepted.body.id]);
assert.deepEqual(steps.rows.map((row) => row.step), ['cache', 'database', 'documents', 'mail', 'search']);

console.log(JSON.stringify({ status: 'resume verified', observed: [...seen], attempts: status.attempts }, null, 2));
await pool.end();

