import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { pool } from '../packages/database/src/pool.js';

const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';

async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}) {
  const init: RequestInit = { method, headers: { authorization: `Bearer ${apiKey}`, ...headers } };
  if (body !== undefined) {
    (init.headers as Record<string, string>)['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  const text = await response.text();
  return { status: response.status, body: text ? JSON.parse(text) : undefined };
}

const mode = process.argv[2];

if (mode === 'request') {
  const suffix = randomUUID().slice(0, 8);
  const customer = (await api('/v1/customers', 'POST', {
    externalReference: `failure-${suffix}`, email: `failure.${suffix}@example.test`, name: 'Failure Subject',
  })).body;
  const accepted = await api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined,
    { 'idempotency-key': `failure-${suffix}` });
  assert.equal(accepted.status, 202);
  let status = accepted.body;
  for (let attempt = 0; attempt < 40 && status.status !== 'failed'; attempt += 1) {
    await new Promise((resolve) => setTimeout(resolve, 500));
    status = (await api(`/v1/erasure-requests/${accepted.body.id}`)).body;
  }
  assert.equal(status.status, 'failed', `expected a failed request, got ${JSON.stringify(status)}`);
  assert.equal(status.lastError, 'search_cleanup_failed', 'error code must be stable');
  assert.ok(!/failure\.|Failure Subject|@/.test(String(status.lastError)), 'error code must not carry customer data');
  assert.equal(status.completedAt, null);
  console.log(JSON.stringify({ status: 'failure reported', requestId: accepted.body.id, customerId: customer.id, email: `failure.${suffix}@example.test` }));
} else {
  const [requestId, customerId, email] = process.argv.slice(3);
  let status = (await api(`/v1/erasure-requests/${requestId}`)).body;
  for (let attempt = 0; attempt < 120 && status.status !== 'completed'; attempt += 1) {
    await new Promise((resolve) => setTimeout(resolve, 1_000));
    status = (await api(`/v1/erasure-requests/${requestId}`)).body;
  }
  assert.equal(status.status, 'completed', `retry did not converge: ${JSON.stringify(status)}`);
  assert.equal(status.lastError, null, 'a completed request must clear the error');
  assert.ok(status.attempts >= 2, `expected retries, got ${status.attempts}`);
  const leftovers = await pool.query(
    `SELECT 1 FROM customers.customers WHERE id=$1
     UNION ALL SELECT 1 FROM operations.analytics_events WHERE COALESCE(email,'')=$2`,
    [customerId, email]);
  assert.equal(leftovers.rowCount, 0, 'retry left personal data behind');
  console.log(JSON.stringify({ status: 'retry converged', attempts: status.attempts }));
}
await pool.end();

