import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { pool } from '../packages/database/src/pool.js';

const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';

async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}) {
  const init: RequestInit = { method, headers: { authorization: `Bearer ${apiKey}`, ...headers } };
  if (body !== undefined) {
    (init.headers as Record<string, string>)['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  const text = await response.text();
  return { status: response.status, body: text ? JSON.parse(text) : undefined };
}

const suffix = randomUUID().slice(0, 8);
const customer = (await api('/v1/customers', 'POST', {
  externalReference: `race-${suffix}`, email: `race.${suffix}@example.test`, name: 'Race Subject',
})).body;

const results = await Promise.all(Array.from({ length: 6 }, (_unused, index) =>
  api(`/v1/customers/${customer.id}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `race-${suffix}-${index}` })));
const accepted = results.filter((result) => result.status === 202);
assert.ok(accepted.length >= 1, JSON.stringify(results));
const ids = new Set(accepted.map((result) => result.body.id));
assert.equal(ids.size, 1, `concurrent requests created ${ids.size} workflows`);

const stored = await pool.query<{ n: string }>(
  `SELECT count(*)::text n FROM privacy.erasure_requests WHERE customer_id=$1`, [customer.id]);
assert.equal(stored.rows[0]!.n, '1', 'more than one request row exists for the customer');

let status = accepted[0]!.body;
for (let attempt = 0; attempt < 80 && status.status !== 'completed'; attempt += 1) {
  await new Promise((resolve) => setTimeout(resolve, 500));
  status = (await api(`/v1/erasure-requests/${status.id}`)).body;
}
assert.equal(status.status, 'completed', JSON.stringify(status));

const audits = await pool.query<{ n: string }>(
  `SELECT count(*)::text n FROM platform.audit_logs
   WHERE target_id=$1 AND action='privacy.erasure.completed'`, [status.id]);
assert.equal(audits.rows[0]!.n, '1', 'destructive work was duplicated');

console.log(JSON.stringify({ status: 'concurrency verified', requestId: status.id, responses: results.map((r) => r.status) }));
await pool.end();

